import{_ as t,o as i,c as a,a2 as o}from"./chunks/framework.e4u2V5E7.js";const m=JSON.parse('{"title":"Production Release Playbook","description":"Engineering playbook for production release workflow","frontmatter":{"title":"Production Release Playbook","description":"Engineering playbook for production release workflow"},"headers":[],"relativePath":"playbooks/production-release.md","filePath":"playbooks/production-release.md","lastUpdated":1784485118000}'),s={name:"playbooks/production-release.md"};function r(l,e,n,d,c,p){return i(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="production-release-playbook" tabindex="-1">Production Release Playbook <a class="header-anchor" href="#production-release-playbook" aria-label="Permalink to &quot;Production Release Playbook&quot;">​</a></h1><h1 id="playbook-production-release" tabindex="-1">Playbook: Production Release <a class="header-anchor" href="#playbook-production-release" aria-label="Permalink to &quot;Playbook: Production Release&quot;">​</a></h1><p><strong>Goal:</strong> Safely deploy changes to production with rollback capability.</p><p><strong>Trigger:</strong> Feature complete, bug fixed, ready to ship.</p><p><strong>Inputs:</strong></p><ul><li>Changes to deploy (feature branch or commits)</li><li>Release type (feature, patch, hotfix)</li><li>Risk level (low, medium, high)</li><li>Deployment platform (Vercel, custom)</li></ul><p><strong>Outputs:</strong></p><ul><li>Deployed production build</li><li>Release verification</li><li>Rollback plan (if needed)</li><li>Release notes</li></ul><p>----|------| | <code>devops</code> | Deployment orchestration, CI/CD | | <code>security</code> | Pre-deployment security check | | <code>performance</code> | Pre-deployment performance check | | <code>reviewer</code> | Final code review | | <code>build</code> | Build verification, deployment execution |</p><h2 id="required-skills" tabindex="-1">Required Skills <a class="header-anchor" href="#required-skills" aria-label="Permalink to &quot;Required Skills&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>When to Load</th></tr></thead><tbody><tr><td><code>vercel-deployment</code></td><td>Vercel-specific deployment</td></tr><tr><td><code>ci-cd-pipelines</code></td><td>CI/CD workflow</td></tr><tr><td><code>docker-patterns</code></td><td>Docker deployment</td></tr><tr><td><code>security-audit</code></td><td>Pre-deployment security</td></tr><tr><td><code>web-performance</code></td><td>Pre-deployment performance</td></tr></tbody></table><h2 id="required-commands" tabindex="-1">Required Commands <a class="header-anchor" href="#required-commands" aria-label="Permalink to &quot;Required Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>When to Use</th></tr></thead><tbody><tr><td><code>/security-scan</code></td><td>Always — pre-deployment security</td></tr><tr><td><code>/performance-check</code></td><td>Always — pre-deployment performance</td></tr><tr><td><code>/deploy-check</code></td><td>Deployment readiness verification</td></tr><tr><td><code>/review</code></td><td>Final code review</td></tr></tbody></table><hr><h2 id="process" tabindex="-1">Process <a class="header-anchor" href="#process" aria-label="Permalink to &quot;Process&quot;">​</a></h2><h3 id="step-1-pre-deployment-checks-15-min" tabindex="-1">Step 1: Pre-Deployment Checks (15 min) <a class="header-anchor" href="#step-1-pre-deployment-checks-15-min" aria-label="Permalink to &quot;Step 1: Pre-Deployment Checks (15 min)&quot;">​</a></h3><ol><li><strong>Code review</strong> — <code>/review</code> on all changes</li><li><strong>Security scan</strong> — <code>/security-scan</code> for vulnerabilities</li><li><strong>Performance check</strong> — <code>/performance-check</code> for regressions</li><li><strong>Build verification</strong> — <code>npm run build</code> passes</li><li><strong>Test verification</strong> — All tests pass</li><li><strong>Lint verification</strong> — No lint errors</li></ol><h3 id="step-2-staging-verification-10-min" tabindex="-1">Step 2: Staging Verification (10 min) <a class="header-anchor" href="#step-2-staging-verification-10-min" aria-label="Permalink to &quot;Step 2: Staging Verification (10 min)&quot;">​</a></h3><ol><li><strong>Preview deployment</strong> — Vercel auto-deploys preview</li><li><strong>Test preview</strong> — Verify functionality</li><li><strong>Check performance</strong> — Lighthouse on preview</li><li><strong>Check security</strong> — Auth flows, API endpoints</li><li><strong>Cross-browser test</strong> — Major browsers</li></ol><h3 id="step-3-deploy-10-min" tabindex="-1">Step 3: Deploy (10 min) <a class="header-anchor" href="#step-3-deploy-10-min" aria-label="Permalink to &quot;Step 3: Deploy (10 min)&quot;">​</a></h3><ol><li><strong>Merge to main</strong> — After approval</li><li><strong>Monitor build</strong> — Watch CI/CD pipeline</li><li><strong>Verify deployment</strong> — Check production URL</li><li><strong>Smoke test</strong> — Critical paths work</li></ol><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Vercel deployment</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # Auto-deploys</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Manual deployment</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vercel</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prod</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Rollback (if needed)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vercel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rollback</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="step-4-post-deployment-verification-10-min" tabindex="-1">Step 4: Post-Deployment Verification (10 min) <a class="header-anchor" href="#step-4-post-deployment-verification-10-min" aria-label="Permalink to &quot;Step 4: Post-Deployment Verification (10 min)&quot;">​</a></h3><ol><li><strong>Smoke test</strong> — Core functionality</li><li><strong>Performance check</strong> — Production metrics</li><li><strong>Error monitoring</strong> — Check for new errors</li><li><strong>Analytics</strong> — Verify tracking works</li><li><strong>User feedback</strong> — Monitor for issues</li></ol><h3 id="step-5-release-5-min" tabindex="-1">Step 5: Release (5 min) <a class="header-anchor" href="#step-5-release-5-min" aria-label="Permalink to &quot;Step 5: Release (5 min)&quot;">​</a></h3><ol><li><strong>Tag release</strong> — <code>git tag v1.0.0</code></li><li><strong>Write release notes</strong> — What changed, why</li><li><strong>Update CHANGELOG.md</strong></li><li><strong>Notify stakeholders</strong></li></ol><hr><h2 id="validation-steps" tabindex="-1">Validation Steps <a class="header-anchor" href="#validation-steps" aria-label="Permalink to &quot;Validation Steps&quot;">​</a></h2><ul><li>[ ] All pre-deployment checks pass</li><li>[ ] Staging verification complete</li><li>[ ] Build succeeds in production</li><li>[ ] Production smoke test passes</li><li>[ ] No new errors in monitoring</li><li>[ ] Rollback plan documented</li><li>[ ] Release notes written</li></ul><h2 id="success-criteria" tabindex="-1">Success Criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success Criteria&quot;">​</a></h2><ul><li>Changes deployed successfully</li><li>No production incidents</li><li>Rollback plan exists (even if not needed)</li><li>Release is documented</li></ul><h2 id="common-pitfalls" tabindex="-1">Common Pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common Pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pitfall</th><th>Why It&#39;s Wrong</th><th>Correct Approach</th></tr></thead><tbody><tr><td>Skipping pre-deployment checks</td><td>Ships bugs to production</td><td>Always run full check suite</td></tr><tr><td>Deploying on Friday</td><td>No time to fix if broken</td><td>Deploy early in week</td></tr><tr><td>No rollback plan</td><td>Stuck if something breaks</td><td>Always have rollback ready</td></tr><tr><td>Deploying without staging test</td><td>Catches issues in production</td><td>Test on staging first</td></tr><tr><td>Big-bang deployment</td><td>Hard to isolate issues</td><td>Deploy in small batches</td></tr><tr><td>Not monitoring after deploy</td><td>Miss production issues</td><td>Monitor for 30+ minutes</td></tr><tr><td>Deploying without review</td><td>Misses code quality issues</td><td>Always review before merge</td></tr></tbody></table><h2 id="related-commands" tabindex="-1">Related Commands <a class="header-anchor" href="#related-commands" aria-label="Permalink to &quot;Related Commands&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/commands/">Commands Registry</a> for commands used in this playbook.</p><h2 id="related-agents" tabindex="-1">Related Agents <a class="header-anchor" href="#related-agents" aria-label="Permalink to &quot;Related Agents&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/agents/">Agents Registry</a> for agents involved in this playbook.</p>`,37)])])}const u=t(s,[["render",r]]);export{m as __pageData,u as default};
